// Converts between the units recipes are written in.

export type Unit = 'g' | 'kg' | 'ml' | 'l' | 'tsp' | 'tbsp' | 'cup';

const GRAMS: Record<string, number> = { g: 1, kg: 1000 };
const MILLILITRES: Record<string, number> = { ml: 1, l: 1000, tsp: 5, tbsp: 15, cup: 240 };

export function convert(amount: number, from: Unit, to: Unit): number {
  if (from in GRAMS && to in GRAMS) {
    return (amount * GRAMS[from]) / GRAMS[to];
  }
  if (from in MILLILITRES && to in MILLILITRES) {
    return (amount * MILLILITRES[from]) / MILLILITRES[to];
  }
  throw new Error(`can't convert ${from} to ${to} without a density`);
}

export function scale(amount: number, servings: number, wanted: number): number {
  return (amount * wanted) / servings;
}

export function format(amount: number, unit: Unit): string {
  const rounded = Math.round(amount * 100) / 100;
  return `${rounded} ${unit}`;
}

tool_input.new_string:
location /tiles/ {
    proxy_pass http://tiles:8080/;
    proxy_cache tiles;
    proxy_cache_valid 200 10m;
    proxy_cache_use_stale error timeout updating;
    proxy_cache_lock on;
    add_header X-Cache-Status $upstream_cache_status;
    expires 10m;
    gzip on;
    gzip_types application/x-protobuf application/json;
    limit_req zone=tiles burst=40 nodelay;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_read_timeout 15s;
}
